<?php require "../vendor/autoload.php"; header("Content-Type: text/plain; charset=utf-8"); $f = ["raport"=>"../RAPORT KELAS 10.xlsx", "nilai"=>"../NILAI GURU MAPEL_DASAR OTOMOTIF _-X TSM (3).xlsx"]; $io = chr(92)."PhpOffice".chr(92)."PhpSpreadsheet".chr(92)."IOFactory"; $co = chr(92)."PhpOffice".chr(92)."PhpSpreadsheet".chr(92)."Cell".chr(92)."Coordinate"; foreach($f as $k=>$p){ echo "=== ".$k." ===".PHP_EOL; if(!file_exists($p)){echo "No file".PHP_EOL;continue;} try { $s = $io::load($p); $ns = $s->getSheetNames(); echo "Sheets: ".implode(", ",$ns).PHP_EOL.PHP_EOL; foreach($ns as $n){ $sh = $s->getSheetByName($n); echo "--- ".$n." ---".PHP_EOL; $mr = min(35,$sh->getHighestRow()); $mc = min(26,$co::columnIndexFromString($sh->getHighestColumn())); for($r=1;$r<=$mr;$r++){ $row = []; for($c=1;$c<=$mc;$c++){ $cell = $sh->getCell($co::stringFromColumnIndex($c).$r); $v = $cell->getValue(); if($cell->isFormula()){try{$v = $cell->getCalculatedValue();}catch(Throwable $e){}} $row[] = $v === null ? "" : (string)$v; } if(trim(implode("", $row))!==""){ echo "R".$r.": ".implode(" | ",array_map(function($x){return substr($x,0,50);},$row)).PHP_EOL; } } echo PHP_EOL; } } catch(Throwable $e){ echo "Err: ".$e->getMessage().PHP_EOL.PHP_EOL; } } ?>
